  Exercise(id: 'Rdead_bug_hold', name: 'Dead Bug Hold', primary: 'abdomen', secondary: ['quads'], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rdead_bug_hold.webp', steps: ['Lie on your back with the arms pointing at the ceiling and the hips and knees bent to 90 degrees.', 'Press the lower back into the floor and keep it there for the whole set.', 'Extend one arm overhead and straighten the opposite leg until both hover just above the floor.', 'Hold that extended position for the prescribed time without letting the ribs flare or the back arch.', 'Return to the start and repeat with the other arm and leg.'], mode: '', kind: 'calisthenics', aliases: ['extended dead bug hold']),
