  Exercise(id: 'Rdecline_db_fly', name: 'Decline Dumbbell Fly', primary: 'chest', secondary: ['shoulders'], equipment: 'Dumbbell', difficulty: 'Intermediate', art: 'rep:rep/Rdecline_db_fly.webp', steps: ['Lie on a decline bench holding dumbbells above your chest.', 'With a slight elbow bend, lower the dumbbells wide to each side.', 'Squeeze the chest to bring them back up.', 'Repeat.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rdeficit_push_ups', name: 'Deficit Push Ups', primary: 'chest', secondary: ['obliques', 'shoulders', 'triceps'], equipment: 'Bodyweight', difficulty: 'Advanced', art: 'rep:rep/Rdeficit_push_ups.webp', steps: ['Place your hands on two elevated surfaces like parallettes or blocks.', 'Assume a plank position with hands under your shoulders.', 'Lower your chest below the level of your hands.', 'Press back up to extend your arms.', 'Repeat for the desired number of reps.'], mode: '', kind: 'calisthenics'),
  Exercise(id: 'Rdiamond_push_ups', name: 'Diamond Push Ups', primary: 'chest', secondary: ['obliques', 'shoulders'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rdiamond_push_ups.webp', steps: ['Assume a push-up position with hands close together forming a diamond.', 'Keep your elbows tucked close to your sides.', 'Lower your chest toward your hands.', 'Press back up to extend your arms.', 'Repeat for the desired number of reps.'], mode: '', kind: 'calisthenics'),
  Exercise(id: 'Rdips', name: 'Chest Dips', primary: 'chest', secondary: ['shoulders'], equipment: 'Other', difficulty: 'Intermediate', art: 'rep:rep/Rdips.webp', steps: ['Grip parallel dip bars and lift yourself to the top position with arms locked.', 'Lean your torso forward slightly.', 'Lower your body by bending your elbows until shoulders are below elbows.', 'Press back up to the starting position.', 'Repeat.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rdolphin_pose', name: 'Dolphin Pose', primary: 'shoulders', secondary: ['hamstrings', 'obliques'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rdolphin_pose.webp', steps: ['Kneel and place the forearms on the floor shoulder-width apart with the elbows under the shoulders.', 'Tuck the toes and lift the hips up and back until the body forms an inverted V.', 'Press the forearms down and draw the shoulders away from the ears; let the heels stay high.', 'Hold the position for the prescribed time, keeping the neck relaxed between the arms.', 'Lower the knees to the floor to come out.'], mode: '', kind: 'calisthenics', aliases: ['ardha pincha mayurasana', 'forearm downward dog']),
  Exercise(id: 'Rdouble_db_kickstand_deadlift', name: 'Double Dumbbell Kickstand Deadlift', primary: 'glutes', secondary: ['back'], equipment: 'Dumbbell', difficulty: 'Intermediate', art: 'rep:rep/Rdouble_db_kickstand_deadlift.webp', steps: ['Stand tall and step one foot back so only the toes touch the floor.', 'Hold a dumbbell in each hand at hip height.', 'Hinge at the hips, lowering both dumbbells toward mid-shin while keeping the back flat.', 'Keep most of your weight on the front foot throughout.', 'Drive through the front heel to return to standing. Switch sides after all reps.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rdouble_db_overhead_carry', name: 'Double Dumbbell Overhead Carry', primary: 'shoulders', secondary: ['abdomen', 'back', 'obliques', 'trapezius', 'triceps'], equipment: 'Dumbbell', difficulty: 'Intermediate', art: 'rep:rep/Rdouble_db_overhead_carry.webp', steps: ['Clean or press a dumbbell to lockout above each shoulder.', 'Straighten both elbows fully and pull your shoulder blades up into the weights rather than shrugging away from them.', 'Brace hard and keep your ribs down — with both arms overhead the temptation to arch is much stronger.', 'Walk forward with short, deliberate strides, keeping both dumbbells stacked over your shoulders.', 'Keep breathing shallowly and steadily instead of holding your breath for the whole carry.', 'Carry for the desired distance, then lower both weights under control.'], mode: '', kind: 'strength', aliases: ['two arm overhead carry', 'dumbbell overhead walk', 'bilateral overhead carry']),
  Exercise(id: 'Rdouble_kettlebell_bicep_curl', name: 'Double Kettlebell Bicep Curl', primary: 'biceps', secondary: ['forearm'], equipment: 'Kettlebell', difficulty: 'Beginner', art: 'rep:rep/Rdouble_kettlebell_bicep_curl.webp', steps: ['Stand holding a kettlebell in each hand by the handle, palms facing forward.', 'Keep the elbows tucked to the sides and the bells hanging at arm length.', 'Curl both kettlebells up toward the shoulders by flexing the elbows.', 'Squeeze the biceps at the top, then lower under control to the starting position.', 'Repeat for the recommended number of repetitions.'], mode: '', kind: 'strength', aliases: ['two-arm kettlebell curl', 'double kb bicep curl']),
  Exercise(id: 'Rdouble_kettlebell_clean', name: 'Double Kettlebell Clean', primary: 'glutes', secondary: ['back', 'forearm', 'shoulders', 'trapezius'], equipment: 'Kettlebell', difficulty: 'Advanced', art: 'rep:rep/Rdouble_kettlebell_clean.webp', steps: ['Stand with two kettlebells on the floor between your feet, handles angled slightly inward.', 'Hinge at the hips, grip the handles, and hike the kettlebells back between the legs.', 'Explosively extend the hips to drive the kettlebells up along the body.', 'As they reach chest height, spear your hands through the handles to catch them at the rack position on the shoulders.', 'Lower back to the hang by hinging at the hips and guiding the bells between the legs.', 'Repeat for the recommended number of repetitions.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rdouble_kettlebell_clean_and_press', name: 'Double Kettlebell Clean and Press', primary: 'shoulders', secondary: ['abdomen', 'glutes', 'quads', 'trapezius', 'triceps'], equipment: 'Kettlebell', difficulty: 'Advanced', art: 'rep:rep/Rdouble_kettlebell_clean_and_press.webp', steps: ['Stand with two kettlebells on the floor between your feet, feet about hip-width apart, and hinge at the hips to grip one handle in each hand.', 'Drive through your legs and extend your hips explosively to pull both kettlebells up, then rotate your elbows under and catch the bells in the racked position at the front of your shoulders.', 'Brace your core and press both kettlebells overhead until your arms are fully locked out.', 'Lower the kettlebells back to the racked position, then down to the floor under control.', 'Repeat for the desired number of reps.'], mode: '', kind: 'strength', aliases: ['double kb clean and press', 'two kettlebell clean and press', 'two-arm kettlebell clean and press', 'double kettlebell clean & press']),
  Exercise(id: 'Rdouble_kettlebell_dead_clean', name: 'Double Kettlebell Dead Clean', primary: 'glutes', secondary: ['back', 'forearm', 'quads', 'trapezius'], equipment: 'Kettlebell', difficulty: 'Intermediate', art: 'rep:rep/Rdouble_kettlebell_dead_clean.webp', steps: ['Set two kettlebells on the floor between your feet.', 'Hinge down and grip both handles.', 'Drive explosively through your legs and hips.', 'Pull the kettlebells up and rotate them to the rack position.', 'Lower them back to the floor and repeat.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rdouble_kettlebell_dead_split_snatch', name: 'Double Kettlebell Dead Split Snatch', primary: 'shoulders', secondary: ['back', 'hamstrings', 'quads', 'trapezius'], equipment: 'Kettlebell', difficulty: 'Intermediate', art: 'rep:rep/Rdouble_kettlebell_dead_split_snatch.webp', steps: ['Set two kettlebells on the floor between your feet.', 'Hinge down and grip both handles firmly.', 'Explosively pull the kettlebells overhead in one motion.', 'Drop into a split stance to catch them at lockout.', 'Recover by stepping feet back together.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rdouble_kettlebell_overhead_carry', name: 'Double Kettlebell Overhead Carry', primary: 'shoulders', secondary: ['abdomen', 'back', 'forearm', 'obliques', 'trapezius', 'triceps'], equipment: 'Kettlebell', difficulty: 'Advanced', art: 'rep:rep/Rdouble_kettlebell_overhead_carry.webp', steps: ['Clean two kettlebells to the rack, then press or push press both to lockout overhead.', 'Straighten both elbows and settle each bell behind and above its wrist, with your wrists straight.', 'Pull your ribs down and brace hard before the first step; with both bells overhead there is nothing to counterbalance with.', 'Walk forward with short, controlled strides, keeping both bells stacked over your shoulders.', 'Keep looking straight ahead and breathe steadily through the carry.', 'Cover the desired distance, then lower both bells to the rack and down under control.'], mode: '', kind: 'strength', aliases: ['double kettlebell waiter walk', 'two kettlebell overhead carry', 'double kb overhead carry', 'bilateral kettlebell overhead carry']),
  Exercise(id: 'Rdouble_kettlebell_overhead_press', name: 'Double Kettlebell Overhead Press', primary: 'shoulders', secondary: ['abdomen', 'obliques', 'trapezius'], equipment: 'Kettlebell', difficulty: 'Intermediate', art: 'rep:rep/Rdouble_kettlebell_overhead_press.webp', steps: ['Clean two kettlebells to the rack position at your shoulders.', 'Stand tall with feet hip-width apart.', 'Press both kettlebells straight overhead.', 'Lock out your arms at the top.', 'Lower back to the rack position and repeat.'], mode: '', kind: 'strength', aliases: ['double kettlebell military press', 'double kb military press', 'double kb press', 'double kb overhead press']),
  Exercise(id: 'Rdouble_kettlebell_rear_delt_row', name: 'Double Kettlebell Rear Delt Row', primary: 'shoulders', secondary: ['back', 'biceps', 'trapezius'], equipment: 'Kettlebell', difficulty: 'Intermediate', art: 'rep:rep/Rdouble_kettlebell_rear_delt_row.webp', steps: ['Stand a kettlebell just outside each foot with your feet about hip-width apart.', 'Hinge at the hips with a flat back until your torso is close to parallel with the floor, letting your knees bend slightly.', 'Take both handles with an overhand grip and let your arms hang straight down from your shoulders.', 'Row both bells up by driving your elbows out to the sides, away from your ribs rather than back along them.', 'Stop when your upper arms are roughly in line with your shoulders, and squeeze your shoulder blades together.', 'Lower the bells under control until your arms hang straight again, and repeat for the desired reps.'], mode: '', kind: 'strength', aliases: ['kettlebell rear delt row', 'two kettlebell rear delt row', 'double kb rear delt row', 'wide elbow kettlebell row', 'double kettlebell high row', 'kettlebell rear deltoid row']),
