  Exercise(id: 'Rdouble_kettlebell_split_jerk', name: 'Double Kettlebell Split Jerk', primary: 'shoulders', secondary: ['glutes', 'trapezius', 'triceps'], equipment: 'Kettlebell', difficulty: 'Intermediate', art: 'rep:rep/Rdouble_kettlebell_split_jerk.webp', steps: ['Clean two kettlebells to the rack position at your shoulders.', 'Dip slightly by bending your knees.', 'Drive the kettlebells overhead explosively.', 'Split your legs to catch them with locked arms.', 'Recover by stepping feet back together.'], mode: '', kind: 'strength'),
