  Exercise(id: 'Rdownward_dog', name: 'Downward-Facing Dog', primary: 'calves', secondary: ['back', 'glutes'], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rdownward_dog.webp', steps: ['Start on all fours with hands slightly ahead of your shoulders.', 'Tuck your toes and lift your hips up and back.', 'Straighten your legs and press your heels toward the floor.', 'Hold for 20 to 30 seconds, breathing steadily.'], mode: 'time', kind: 'stretch'),
  Exercise(id: 'Rdownward_dog_knee_tuck', name: 'Downward Dog Knee Tuck', primary: 'quads', secondary: ['abdomen', 'obliques', 'shoulders'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rdownward_dog_knee_tuck.webp', steps: ['Set up in downward dog with the hands shoulder-width apart and the hips high.', 'Press the floor away and brace the trunk so the lower back stays long.', 'Draw one knee in towards the chest, rounding the upper back slightly as it comes in.', 'Extend the leg back to the starting position under control.', 'Repeat with the other leg and keep alternating for the desired number of repetitions.'], mode: '', kind: 'calisthenics', aliases: ['down dog knee to chest', 'knee to nose', 'pike knee tuck', 'downward dog knee drive']),
  Exercise(id: 'Rdownward_dog_pedal', name: 'Downward Dog Pedal', primary: 'calves', secondary: ['hamstrings'], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rdownward_dog_pedal.webp', steps: ['Set up in downward dog with the hands shoulder-width apart and the hips high.', 'Bend one knee and let that heel lift while the opposite heel presses down towards the floor.', 'Switch sides smoothly, as if pedalling, keeping the hips high throughout.', 'Keep the hands pressing evenly so the shoulders stay stable.', 'Continue alternating for the desired number of repetitions or time.'], mode: 'time', kind: 'stretch', aliases: ['downward dog pedals', 'pedalling the feet', 'bicycle the legs in down dog']),
