  Exercise(id: 'Rdownward_dog_to_low_lunge', name: 'Downward Dog to Low Lunge', primary: 'quads', secondary: ['glutes'], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rdownward_dog_to_low_lunge.webp', steps: ['Start in downward dog with the hands shoulder-width apart.', 'Shift the weight forward and step one foot up between the hands.', 'Lower the back knee to the floor and sink the hips into a low lunge.', 'Press back through the hands, lift the back knee and step the front foot back to downward dog.', 'Repeat on the other side and keep alternating.'], mode: 'time', kind: 'stretch', aliases: ['step-through to low lunge', 'low lunge step through']),
