  Exercise(id: 'Rdownward_dog_to_upward_dog', name: 'Downward Dog to Upward Dog', primary: 'shoulders', secondary: ['chest', 'obliques', 'triceps'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rdownward_dog_to_upward_dog.webp', steps: ['Start in downward dog with the hips high and the hands shoulder-width apart.', 'Shift forward through plank and lower slightly, then press the chest through into upward dog with the thighs off the floor.', 'Draw the shoulders back and down and keep the neck long.', 'Tuck the toes, press the floor away and lift the hips back into downward dog.', 'Continue moving between the two positions for the desired number of repetitions.'], mode: '', kind: 'calisthenics', aliases: ['dog to dog flow', 'up dog down dog flow']),
  Exercise(id: 'Rdumbbell_bench_pull', name: 'Dumbbell Bench Pull', primary: 'back', secondary: ['biceps', 'shoulders'], equipment: 'Dumbbell', difficulty: 'Intermediate', art: 'rep:rep/Rdumbbell_bench_pull.webp', steps: ['Lie face down on an incline bench holding dumbbells.', 'Let your arms hang straight down.', 'Pull the dumbbells up toward your chest, squeezing your shoulder blades.', 'Lower with control.', 'Repeat.'], mode: '', kind: 'strength'),
