  Exercise(id: 'Rdumbbell_farmers_walk', name: 'Dumbbell Farmer\'s Walk', primary: 'forearm', secondary: ['abdomen', 'glutes', 'obliques', 'quads'], equipment: 'Dumbbell', difficulty: 'Beginner', art: 'rep:rep/Rdumbbell_farmers_walk.webp', steps: ['Stand tall with a dumbbell in each hand, arms extended at your sides.', 'Retract your shoulder blades and brace your core, maintaining a neutral spine.', 'Walk slowly and deliberately for a set distance or duration, taking short, controlled steps.', 'Keep your chest up and avoid leaning to one side as you walk.', 'Focus on maintaining a strong, stable posture throughout the movement.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rdumbbell_front_squat', name: 'Dumbbell Front Squat', primary: 'glutes', secondary: ['abdomen', 'back', 'hamstrings'], equipment: 'Dumbbell', difficulty: 'Intermediate', art: 'rep:rep/Rdumbbell_front_squat.webp', steps: ['Hold a dumbbell in each hand resting on top of your shoulders.', 'Keep your elbows high and torso upright.', 'Lower your hips by bending knees until thighs are parallel to the floor.', 'Drive through your heels to stand back up.', 'Maintain a neutral spine throughout.', 'Repeat for the desired number of reps.'], mode: '', kind: 'strength'),
