  Exercise(id: 'Rdumbbell_snatch', name: 'Dumbbell Snatch', primary: 'shoulders', secondary: ['back', 'hamstrings', 'quads'], equipment: 'Dumbbell', difficulty: 'Intermediate', art: 'rep:rep/Rdumbbell_snatch.webp', steps: ['Stand with feet shoulder-width apart, dumbbell on the floor between your feet.', 'Hinge and grip the dumbbell with one hand.', 'Explosively extend hips, knees, and ankles to pull the dumbbell upward.', 'Punch the dumbbell overhead in one fluid motion.', 'Lock out your arm and stabilize at the top.', 'Complete reps on one side, then switch.'], mode: '', kind: 'strength'),
