  Exercise(id: 'Rdumbbell_tricep_extension', name: 'Dumbbell Tricep Extension', primary: 'triceps', secondary: [], equipment: 'Dumbbell', difficulty: 'Beginner', art: 'rep:rep/Rdumbbell_tricep_extension.webp', steps: ['Stand holding a dumbbell in one hand overhead.', 'Lower the dumbbell behind your head by bending your elbow.', 'Extend your arm back to the starting position.', 'Keep your elbow close to your head.', 'Repeat on both sides.'], mode: '', kind: 'strength'),
