  Exercise(id: 'Reagle_pose', name: 'Eagle Pose', primary: 'glutes', secondary: ['shoulders', 'trapezius'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Reagle_pose.webp', steps: ['Stand tall, bend both knees slightly and shift the weight onto one foot.', 'Cross the other thigh over the standing thigh and hook the foot behind the calf if it reaches.', 'Cross the opposite arm underneath, wind the forearms and bring the palms towards each other.', 'Sit down a little into the standing leg and hold for the prescribed time with the elbows lifted.', 'Unwind and repeat on the other side.'], mode: '', kind: 'calisthenics', aliases: ['garudasana']),
