  Exercise(id: 'Rsingle_leg_calf_raise', name: 'Single Leg Calf Raise', primary: 'calves', secondary: [], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rsingle_leg_calf_raise.webp', steps: ['Stand on one foot with the ball of the foot on a raised platform, heel free.', 'Hold a wall or rail for balance with one hand.', 'Drop the heel below platform level for a deep stretch.', 'Drive up onto the toes as high as possible.', 'Lower under control. Complete reps per side, then switch.'], mode: '', kind: 'calisthenics'),
