  Exercise(id: 'Rsingle_leg_glute_bridge_hold', name: 'Single-Leg Glute Bridge Hold', primary: 'glutes', secondary: ['back', 'hamstrings'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rsingle_leg_glute_bridge_hold.webp', steps: ['Lie on your back with one knee bent and that foot flat, and lift the other leg so the thigh is roughly vertical.', 'Push through the heel of the planted foot and lift the hips until the body is straight from the knee to the shoulders.', 'Level the pelvis so the lifted side does not drop, and tuck the ribs down.', 'Hold the top position for the prescribed time, keeping the lifted knee still.', 'Lower the hips under control and repeat on the other side.'], mode: '', kind: 'calisthenics', aliases: ['single leg bridge hold', 'one leg glute bridge hold']),
  Exercise(id: 'Rsingle_leg_lying_leg_curl', name: 'Single Leg Lying Leg Curl', primary: 'hamstrings', secondary: ['calves'], equipment: 'Machine', difficulty: 'Intermediate', art: 'rep:rep/Rsingle_leg_lying_leg_curl.webp', steps: ['Lie face down on a lying leg curl machine.', 'Position one ankle under the pad, keeping the other foot off the machine.', 'Curl the working leg by bringing your heel toward your glute.', 'Squeeze the hamstring at the top.', 'Lower the leg back down under control.', 'Complete reps on one side, then switch.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rsingle_leg_press', name: 'Single Leg Press', primary: 'glutes', secondary: ['hamstrings'], equipment: 'Machine', difficulty: 'Intermediate', art: 'rep:rep/Rsingle_leg_press.webp', steps: ['Sit in a leg press machine with one foot placed on the platform.', 'Keep the other leg off the platform, resting to the side.', 'Release the safeties and lower the platform by bending your knee.', 'Stop when your knee is near a 90-degree angle.', 'Drive through the heel to press the platform back up.', 'Complete reps on one side, then switch.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rsit_ups', name: 'Sit-Ups', primary: 'quads', secondary: ['obliques'], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rsit_ups.webp', steps: ['Lie on your back with knees bent and feet anchored.', 'Cross your arms over your chest or place hands behind your head.', 'Sit all the way up until your torso is upright.', 'Lower back down with control.', 'Repeat.'], mode: '', kind: 'calisthenics'),
