  Exercise(id: 'Rskull_crusher', name: 'Skull Crusher', primary: 'triceps', secondary: [], equipment: 'Barbell', difficulty: 'Intermediate', art: 'rep:rep/Rskull_crusher.webp', steps: ['Lie on a flat bench holding a barbell over your chest with a narrow grip.', 'Lower the bar toward your forehead by bending at the elbows.', 'Extend your arms back to the start.', 'Repeat.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rsmith_machine_decline_bench_press', name: 'Smith Machine Decline Bench Press', primary: 'chest', secondary: ['shoulders', 'triceps'], equipment: 'Machine', difficulty: 'Beginner', art: 'rep:rep/Rsmith_machine_decline_bench_press.webp', steps: ['Set a decline bench in the machine so the bar lines up with your lower chest when you lie down, and hook your legs under the pads.', 'Lie back with your head at the low end, take an overhand grip slightly wider than your shoulders and unrack the bar.', 'Lower the bar under control until it touches your lower chest, keeping your elbows at roughly forty-five degrees from your torso.', 'Press the bar back up until your arms are extended, without locking the elbows out hard.', 'Repeat for the desired number of repetitions, then rack the bar before releasing your legs.'], mode: '', kind: 'strength', aliases: ['smith decline press', 'decline press on smith machine', 'decline bench press on smith machine', 'smith machine decline chest press', 'guided decline bench press']),
  Exercise(id: 'Rsmith_machine_front_squat', name: 'Smith Machine Front Squat', primary: 'glutes', secondary: ['back', 'hamstrings'], equipment: 'Machine', difficulty: 'Beginner', art: 'rep:rep/Rsmith_machine_front_squat.webp', steps: ['Set the bar at upper-chest height and step under it so it rests across the front of your shoulders, against your collarbones.', 'Cross your arms over the bar or take an open front-rack grip, and drive your elbows up until your upper arms are close to parallel with the floor.', 'Unrack the bar and stand with your feet about shoulder-width apart and slightly forward of it.', 'Sit straight down, keeping your elbows high and your torso upright, until your thighs are at least parallel to the floor.', 'Drive through the middle of your feet to stand back up, and repeat for the desired number of repetitions.'], mode: '', kind: 'strength', aliases: ['smith front squat', 'front squat on smith machine', 'front rack smith squat', 'machine front squat', 'guided front squat']),
  Exercise(id: 'Rsmith_machine_rdl', name: 'Smith Machine Romanian Deadlift', primary: 'hamstrings', secondary: ['back', 'glutes', 'trapezius'], equipment: 'Machine', difficulty: 'Beginner', art: 'rep:rep/Rsmith_machine_rdl.webp', steps: ['Set the Smith machine bar at mid-thigh height and stand directly underneath with feet hip-width.', 'Unrack the bar with an overhand grip just outside the hips.', 'Push the hips back while letting the bar slide down the front of the legs.', 'Go until you feel a deep hamstring stretch, with a flat back and a soft knee bend.', 'Drive the hips forward to return to standing, keeping the bar close to the body.', 'Repeat for the recommended number of repetitions.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rsmith_machine_reverse_grip_bent_over_row', name: 'Smith Machine Reverse Grip Bent Over Row', primary: 'biceps', secondary: ['back', 'trapezius'], equipment: 'Machine', difficulty: 'Beginner', art: 'rep:rep/Rsmith_machine_reverse_grip_bent_over_row.webp', steps: ['Stand inside a Smith machine and grip the bar with an underhand grip.', 'Hinge forward at the hips until your torso is about 45 degrees.', 'Keep your back flat and core braced.', 'Pull the bar toward your lower abdomen.', 'Squeeze your lats and shoulder blades at the top.', 'Lower the bar under control and repeat.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rsmith_machine_shoulder_press', name: 'Smith Machine Shoulder Press', primary: 'shoulders', secondary: ['trapezius', 'triceps'], equipment: 'Machine', difficulty: 'Beginner', art: 'rep:rep/Rsmith_machine_shoulder_press.webp', steps: ['Sit on a bench positioned inside a Smith machine.', 'Grip the bar slightly wider than shoulder-width at shoulder level.', 'Unrack the bar and press it overhead until your arms are extended.', 'Lower the bar back to shoulder level under control.', 'Keep your core tight throughout.', 'Repeat for the desired number of reps.'], mode: '', kind: 'strength'),
