  Exercise(id: 'Rsmith_machine_split_squat', name: 'Smith Machine Split Squat', primary: 'glutes', secondary: ['hamstrings'], equipment: 'Machine', difficulty: 'Intermediate', art: 'rep:rep/Rsmith_machine_split_squat.webp', steps: ['Set the bar low enough that it will still clear your shoulders at the bottom of the rep, then step under it and rest it across your upper traps.', 'Unrack the bar and take a long stride forward with one foot, leaving the rear foot planted on the floor with the heel lifted.', 'Check that your front shin will stay roughly vertical when you descend; adjust the stride length before you start loading it.', 'Lower straight down by bending both knees until the rear knee is just above the floor and the front thigh is close to parallel.', 'Drive through the front heel to return to the start, keeping both feet in place, and repeat for the desired reps before switching sides.'], mode: '', kind: 'strength', aliases: ['smith split squat', 'static lunge on smith machine', 'smith machine static lunge', 'stationary lunge smith machine', 'split squat on smith machine']),
  Exercise(id: 'Rsphinx_pose', name: 'Sphinx Pose', primary: 'back', secondary: ['chest', 'quads'], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rsphinx_pose.webp', steps: ['Lie face down and place the forearms on the floor with the elbows directly under the shoulders.', 'Press the forearms and the tops of the feet down and lift the chest.', 'Draw the shoulders away from the ears and lengthen the back of the neck.', 'Hold the position for the prescribed time, breathing into the front of the chest.', 'Lower the chest to the floor and rest.'], mode: 'time', kind: 'stretch', aliases: ['salamba bhujangasana', 'forearm cobra']),
  Exercise(id: 'Rsplit_squat', name: 'Split Squat', primary: 'glutes', secondary: ['hamstrings'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rsplit_squat.webp', steps: ['Stand in a split stance with one foot forward and one back.', 'Keep your torso upright and core braced.', 'Lower your hips straight down by bending both knees.', 'Stop when the back knee is just above the floor.', 'Drive through the front heel to return to the start.', 'Complete reps on one side, then switch.'], mode: '', kind: 'calisthenics'),
  Exercise(id: 'Rspoto_press', name: 'Spoto Press', primary: 'chest', secondary: ['shoulders', 'triceps'], equipment: 'Barbell', difficulty: 'Intermediate', art: 'rep:rep/Rspoto_press.webp', steps: ['Lie on a flat bench and grip the barbell slightly wider than shoulders.', 'Unrack the bar and hold it over your chest with arms extended.', 'Lower the bar until it is one inch above your chest.', 'Pause there for a full second without touching the chest.', 'Press the bar back up until your arms are extended.', 'Repeat for the desired number of reps.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rsquat', name: 'Barbell Back Squat', primary: 'glutes', secondary: ['back', 'hamstrings'], equipment: 'Barbell', difficulty: 'Intermediate', art: 'rep:rep/Rsquat.webp', steps: ['Position the bar on your upper traps.', 'Unrack and step back, feet shoulder-width apart.', 'Brace your core and squat down until thighs are parallel.', 'Drive through your heels to stand back up.', 'Repeat.'], mode: '', kind: 'strength'),
