  Exercise(id: 'Rthruster', name: 'Thruster', primary: 'shoulders', secondary: ['glutes', 'trapezius', 'triceps'], equipment: 'Barbell', difficulty: 'Intermediate', art: 'rep:rep/Rthruster.webp', steps: ['Hold a barbell in a front rack position with elbows high.', 'Stand with feet shoulder-width apart.', 'Squat down to parallel while keeping your torso upright.', 'Drive up out of the squat and press the bar overhead in one motion.', 'Lock out your arms at the top with the bar overhead.', 'Lower the bar back to the front rack and repeat.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtoes_to_bar', name: 'Toes to Bar', primary: 'quads', secondary: ['back', 'forearm', 'obliques'], equipment: 'Other', difficulty: 'Intermediate', art: 'rep:rep/Rtoes_to_bar.webp', steps: ['Hang from a pull-up bar with an overhand grip, arms fully extended and body still.', 'Engage your lats and core to prevent swinging.', 'Raise your legs with straight knees, reaching your toes up toward the bar.', 'Touch the bar with your toes, then lower your legs under control.', 'Repeat for the desired reps.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtorso_twists', name: 'Torso Twists', primary: 'obliques', secondary: ['back'], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rtorso_twists.webp', steps: ['Stand with the feet about shoulder-width apart and the knees softly bent.', 'Brace lightly and hold the hands together in front of the chest.', 'Rotate the rib cage to one side without shifting the feet.', 'Return through centre and rotate to the other side.', 'Continue alternating smoothly through a comfortable range.'], mode: 'time', kind: 'stretch'),
  Exercise(id: 'Rtree_pose', name: 'Tree Pose', primary: 'glutes', secondary: ['back', 'calves'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rtree_pose.webp', steps: ['Stand tall and shift the weight onto one foot.', 'Place the sole of the other foot on the inner calf or the inner thigh, avoiding the knee.', 'Press the foot and the leg into each other and level the hips.', 'Bring the hands to the chest or overhead and hold for the prescribed time.', 'Lower the foot and repeat on the other side.'], mode: '', kind: 'calisthenics', aliases: ['vrksasana']),
  Exercise(id: 'Rtriangle_pose', name: 'Triangle Pose', primary: 'hamstrings', secondary: ['glutes'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rtriangle_pose.webp', steps: ['Stand wide with the front foot turned out and the back foot angled slightly in.', 'Keep both legs straight and reach the front hand forward as the hips shift back.', 'Tilt sideways and bring the bottom hand to the shin, a block or the floor, top arm reaching up.', 'Hold the position for the prescribed time, turning the chest towards the ceiling.', 'Press into the feet to come up and repeat on the other side.'], mode: 'time', kind: 'stretch', aliases: ['trikonasana', 'utthita trikonasana']),
  Exercise(id: 'Rtricep_kickback', name: 'Dumbbell Tricep Kickback', primary: 'triceps', secondary: [], equipment: 'Dumbbell', difficulty: 'Beginner', art: 'rep:rep/Rtricep_kickback.webp', steps: ['Hinge forward at the hips, holding a dumbbell with elbow bent at 90 degrees.', 'Extend your arm straight back, squeezing the tricep.', 'Hold briefly at full extension.', 'Lower with control.', 'Repeat on both sides.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtricep_pushdown', name: 'Cable Tricep Pushdown', primary: 'triceps', secondary: [], equipment: 'Cable', difficulty: 'Beginner', art: 'rep:rep/Rtricep_pushdown.webp', steps: ['Stand facing a cable machine with a straight bar attachment.', 'Grip the bar and pin your elbows to your sides.', 'Push the bar down until your arms are fully extended.', 'Slowly return to the starting position.', 'Repeat.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_bicep_curl', name: 'TRX Bicep Curl', primary: 'biceps', secondary: ['forearm'], equipment: 'Other', difficulty: 'Beginner', art: 'rep:rep/Rtrx_bicep_curl.webp', steps: ['Adjust the suspension trainer straps to a medium length.', 'Stand facing the anchor point, grasp the handles with an underhand grip, and lean back until your arms are fully extended.', 'Keep your body straight and core engaged, pull your chest towards your hands by bending your elbows.', 'Squeeze your biceps at the top of the movement.', 'Slowly extend your arms back to the starting position, controlling the descent.', 'Maintain tension throughout the set.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_chest_press', name: 'TRX Chest Press', primary: 'chest', secondary: ['abdomen', 'shoulders', 'triceps'], equipment: 'Other', difficulty: 'Beginner', art: 'rep:rep/Rtrx_chest_press.webp', steps: ['Adjust the suspension trainer handles to mid-calf height.', 'Stand facing away from the anchor point, holding a handle in each hand, arms extended.', 'Lean forward into a plank position, keeping your body straight from head to heels.', 'Lower your chest towards your hands by bending your elbows, maintaining tension in the straps.', 'Press back up to the starting position, fully extending your arms and squeezing your chest.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_face_pull', name: 'TRX Face Pull', primary: 'shoulders', secondary: ['trapezius'], equipment: 'Other', difficulty: 'Beginner', art: 'rep:rep/Rtrx_face_pull.webp', steps: ['Grasp the TRX handles with an overhand grip, palms facing down.', 'Lean back until your arms are fully extended and your body forms a straight line.', 'Pull the handles towards your face, driving your elbows high and wide.', 'Squeeze your shoulder blades together at the peak contraction.', 'Slowly extend your arms back to the starting position with control.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_hamstring_curl', name: 'TRX Hamstring Curl', primary: 'hamstrings', secondary: ['calves', 'glutes'], equipment: 'Other', difficulty: 'Intermediate', art: 'rep:rep/Rtrx_hamstring_curl.webp', steps: ['Lie on your back with heels in the suspension trainer cradles, knees bent at 90 degrees.', 'Lift your hips off the floor, creating a straight line from knees to shoulders.', 'Extend your legs forward, maintaining hip elevation and core tension.', 'Pull your heels back towards your glutes, contracting your hamstrings forcefully.', 'Control the movement, avoiding any drop in hip height throughout the set.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_lunge', name: 'TRX Lunge', primary: 'glutes', secondary: ['hamstrings'], equipment: 'Other', difficulty: 'Beginner', art: 'rep:rep/Rtrx_lunge.webp', steps: ['Stand facing away from the anchor point, holding the suspension trainer handles in front of you.', 'Place one foot into both foot cradles, extending the leg behind you.', 'Brace your core and lower your body by bending the front knee, keeping your torso upright.', 'Descend until your front thigh is parallel to the floor or just below, maintaining tension on the suspension trainer.', 'Drive through your front heel to return to the starting position, extending the front leg.', 'Complete all reps on one side, then switch legs and repeat per side.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_pistol_squat', name: 'TRX Pistol Squat', primary: 'glutes', secondary: ['hamstrings'], equipment: 'Other', difficulty: 'Intermediate', art: 'rep:rep/Rtrx_pistol_squat.webp', steps: ['Anchor the suspension trainer and hold the handles with both hands, arms extended.', 'Stand tall, lift one leg straight out in front of you, keeping it off the ground.', 'Initiate the squat by pushing your hips back and bending the standing knee, lowering your body as deep as possible.', 'Keep your chest up, back straight, and use the TRX for balance and support as needed.', 'Drive through your heel to return to the starting position, extending the standing leg fully.', 'Complete all reps on one side before switching to the other.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_plank', name: 'TRX Plank', primary: 'abdomen', secondary: ['obliques', 'shoulders'], equipment: 'Other', difficulty: 'Intermediate', art: 'rep:rep/Rtrx_plank.webp', steps: ['Place both feet in the TRX foot cradles.', 'Assume a forearm or high plank position on the floor.', 'Keep your body in a straight line from head to heels.', 'Brace your core and squeeze your glutes.', 'Hold the position for the desired time.', 'Lower your knees to exit safely.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_row', name: 'TRX Row', primary: 'back', secondary: ['biceps', 'shoulders', 'trapezius'], equipment: 'Other', difficulty: 'Beginner', art: 'rep:rep/Rtrx_row.webp', steps: ['Grasp the handles of a suspension trainer with an overhand grip, palms facing each other.', 'Lean back, extending your arms fully, keeping your body straight from head to heels.', 'Engage your core and pull your chest towards your hands, squeezing your shoulder blades together.', 'Pause briefly at the top, then slowly lower yourself back to the starting position with control.', 'Maintain a rigid body throughout the movement, avoiding any sagging in the hips.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_side_plank', name: 'TRX Side Plank', primary: 'obliques', secondary: ['glutes', 'shoulders'], equipment: 'Other', difficulty: 'Intermediate', art: 'rep:rep/Rtrx_side_plank.webp', steps: ['Place both feet in the TRX foot cradles and lie on your side.', 'Prop up on your bottom forearm with your elbow under your shoulder.', 'Lift your hips so your body forms a straight line.', 'Stack your top foot over the bottom foot.', 'Hold the position while breathing steadily.', 'Lower and switch sides after the set.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_squat', name: 'TRX Squat', primary: 'glutes', secondary: ['hamstrings'], equipment: 'Other', difficulty: 'Beginner', art: 'rep:rep/Rtrx_squat.webp', steps: ['Stand facing the anchor point, holding the handles with palms facing each other, arms extended.', 'Lean back slightly, keeping your body straight and core engaged, with feet shoulder-width apart.', 'Initiate the squat by pushing your hips back and bending your knees, lowering your body as if sitting in a chair.', 'Descend until your thighs are parallel to the floor or as deep as comfortable, maintaining tension on the straps.', 'Drive through your heels to return to the starting position, extending your hips and knees fully.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_tricep_extension', name: 'TRX Triceps Extension', primary: 'triceps', secondary: [], equipment: 'Other', difficulty: 'Intermediate', art: 'rep:rep/Rtrx_tricep_extension.webp', steps: ['Stand facing the anchor point, holding the TRX handles with an overhand grip, palms facing down.', 'Lean forward, extending your arms straight out in front of you at shoulder height, creating tension in the straps.', 'Keeping your elbows high and fixed, bend them to lower your body by letting your hands move towards your temples.', 'Extend your elbows forcefully to push your body back to the starting position, squeezing your triceps.', 'Maintain a rigid plank position throughout the movement, engaging your core and glutes.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rtrx_y_fly', name: 'TRX Y-Fly', primary: 'shoulders', secondary: ['back'], equipment: 'Other', difficulty: 'Intermediate', art: 'rep:rep/Rtrx_y_fly.webp', steps: ['Stand facing the anchor point, holding the handles with an overhand grip, palms facing each other.', 'Lean back, extending your arms straight in front of you, maintaining a plank position with your body.', 'Initiate the movement by pulling your shoulder blades together and down, forming a \'Y\' shape with your body.', 'Keep your arms straight and elbows slightly bent, squeezing your shoulder blades at the top.', 'Slowly control the descent back to the starting position, resisting the pull of the straps.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rv_bar_lat_pulldown', name: 'V-Bar Lat Pulldown', primary: 'back', secondary: ['biceps', 'trapezius'], equipment: 'Machine', difficulty: 'Beginner', art: 'rep:rep/Rv_bar_lat_pulldown.webp', steps: ['Attach a V-bar (double-D handle) to a lat pulldown cable.', 'Sit with the thighs secured under the pad and grip the handle, palms facing each other.', 'Begin with the arms fully extended overhead.', 'Pull the handle down to the sternum by driving the elbows down and slightly back.', 'Squeeze the lats at the bottom, then return slowly under control.', 'Repeat for the recommended number of repetitions.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rv_bar_tricep_pushdown', name: 'V-Bar Tricep Pushdown', primary: 'triceps', secondary: [], equipment: 'Cable', difficulty: 'Beginner', art: 'rep:rep/Rv_bar_tricep_pushdown.webp', steps: ['Attach a V-bar handle to a high cable pulley.', 'Stand facing the stack and grip the V-bar with both hands, palms down.', 'Start with the elbows tucked to the sides, forearms parallel to the floor.', 'Press the handle down until the arms are fully extended.', 'Squeeze the triceps, then return under control to the starting position.', 'Repeat for the recommended number of repetitions.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rv_sit', name: 'V-Sit', primary: 'quads', secondary: ['obliques'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rv_sit.webp', steps: ['Sit on the floor with your legs extended in front of you.', 'Lean back slightly and lift your legs off the floor.', 'Reach your arms forward so your body forms a V shape.', 'Balance on your sit bones with core tight.', 'Hold the position while breathing steadily.', 'Lower your legs and torso to exit.'], mode: '', kind: 'calisthenics'),
  Exercise(id: 'Rv_ups', name: 'V Ups', primary: 'quads', secondary: ['abdomen', 'obliques'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rv_ups.webp', steps: ['Lie flat on your back with arms extended overhead and legs straight.', 'Simultaneously raise your legs and upper body toward each other.', 'Reach your hands toward your feet at the top, forming a V shape.', 'Keep your legs straight throughout the movement.', 'Lower both ends under control back to the floor.', 'Repeat for the desired number of reps.'], mode: '', kind: 'calisthenics'),
  Exercise(id: 'Rwall_push_ups', name: 'Wall Push Ups', primary: 'chest', secondary: ['shoulders', 'triceps'], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rwall_push_ups.webp', steps: ['Stand facing a wall and place your palms on it at shoulder height.', 'Step your feet back until your arms are fully extended.', 'Bend your elbows to bring your chest toward the wall.', 'Keep your body in a straight line throughout.', 'Press back to the starting position.', 'Repeat for the desired number of reps.'], mode: '', kind: 'calisthenics'),
  Exercise(id: 'Rwarrior_one', name: 'Warrior I', primary: 'glutes', secondary: ['back', 'shoulders'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rwarrior_one.webp', steps: ['Step one foot back and turn it out about forty-five degrees, planting the whole sole.', 'Bend the front knee until it stacks over the ankle and keep the back leg straight.', 'Draw both hip points towards the front of the mat and lift the arms overhead.', 'Hold the position for the prescribed time with the ribs down and the chest lifted.', 'Step the feet together and repeat on the other side.'], mode: '', kind: 'calisthenics', aliases: ['virabhadrasana i', 'warrior 1', 'warrior one']),
  Exercise(id: 'Rwarrior_three', name: 'Warrior III', primary: 'glutes', secondary: ['back'], equipment: 'Bodyweight', difficulty: 'Intermediate', art: 'rep:rep/Rwarrior_three.webp', steps: ['Stand on one leg with the knee soft and the hips level.', 'Hinge forward from the hips as the other leg lifts behind you.', 'Continue until the torso and the lifted leg are roughly parallel to the floor.', 'Reach the arms forward, back along the body or out to the sides, and hold for the prescribed time.', 'Lower the leg and repeat on the other side.'], mode: '', kind: 'calisthenics', aliases: ['virabhadrasana iii', 'warrior 3', 'warrior three']),
