  Exercise(id: 'Rwide_grip_bench_press', name: 'Wide-Grip Bench Press', primary: 'chest', secondary: ['shoulders', 'triceps'], equipment: 'Barbell', difficulty: 'Intermediate', art: 'rep:rep/Rwide_grip_bench_press.webp', steps: ['Lie on a flat bench. Grip the barbell wider than shoulder-width.', 'Lower the bar to mid-chest.', 'Press back up to full extension.', 'Repeat.'], mode: '', kind: 'strength'),
