  Exercise(id: 'Rwide_grip_seated_cable_row', name: 'Wide Grip Seated Cable Row', primary: 'back', secondary: ['biceps', 'shoulders'], equipment: 'Cable', difficulty: 'Intermediate', art: 'rep:rep/Rwide_grip_seated_cable_row.webp', steps: ['Sit at a cable row station with feet on the platform.', 'Grip a wide bar with an overhand grip.', 'Pull the bar toward your upper abdomen, squeezing your shoulder blades.', 'Extend your arms back to the starting position with control.', 'Repeat.'], mode: '', kind: 'strength'),
  Exercise(id: 'Rwide_legged_forward_fold', name: 'Wide-Legged Forward Fold', primary: 'glutes', secondary: ['back', 'calves'], equipment: 'Bodyweight', difficulty: 'Beginner', art: 'rep:rep/Rwide_legged_forward_fold.webp', steps: ['Stand with the feet wide apart and the outer edges parallel.', 'Place the hands on the hips, lift the chest and hinge forward from the hip joints.', 'Bring the hands to the floor under the shoulders and let the head hang.', 'Hold the fold for the prescribed time, shifting the weight slightly into the balls of the feet.', 'Bring the hands back to the hips and come up with a flat back.'], mode: 'time', kind: 'stretch', aliases: ['prasarita padottanasana', 'wide leg forward fold']),
  Exercise(id: 'Rwide_stance_leg_press', name: 'Wide-Stance Leg Press', primary: 'glutes', secondary: ['hamstrings', 'quads'], equipment: 'Machine', difficulty: 'Beginner', art: 'rep:rep/Rwide_stance_leg_press.webp', steps: ['Set the back pad and seat so your lower back remains supported at the bottom of the repetition.', 'Place your feet wide on the platform with the toes turned out only as far as the knees can follow comfortably.', 'Lower the sled by bending the hips and knees while keeping the knees aligned with the toes and the feet flat.', 'Press through the whole foot and extend the hips and knees without forcing the knees into lockout.', 'Lower the sled under control and repeat for the desired number of repetitions.'], mode: '', kind: 'strength', aliases: ['wide foot leg press', 'adductor biased leg press', 'wide leg press']),
  Exercise(id: 'Rwrist_curl', name: 'Bilateral Dumbbell Wrist Curl', primary: 'forearm', secondary: [], equipment: 'Dumbbell', difficulty: 'Beginner', art: 'rep:rep/Rwrist_curl.webp', steps: ['Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms up.', 'Let both dumbbells roll down to your fingertips.', 'Curl both dumbbells up by flexing your wrists.', 'Squeeze at the top, then lower under control.', 'Repeat for the desired number of reps.'], mode: '', kind: 'strength', aliases: ['double dumbbell wrist curl']),
];

